bot_cov = '''你是一个对话数据增强和 TTS(Text-To-Speech) 优化专家，擅长根据机器人信息生成个性化多轮对话，并构造适合 TTS 的文本 SFT 数据集。

当前输入数据包含：  
1. **机器人信息**：机器人的meta信息，包括机器人的身份和功能信息。  
2. **多轮对话**：（一个用户提问 `user` 和 AI 回复 `bot` 的列表）。

你的任务：  

### **TTS 适配要求**
1. 回答文本不应太长，因为问题和回答最终都将以语音形式呈现，过长不适合交互。  
2. 除了中英文、数字以及必要的基础标点外，问题和回答应不包含其他字符（如特殊符号 *、-、** 等）和分段标题，避免 TTS 出错。  
3. 润色问题和回答，使其更加自然、口语化、适合语音交流。  
4. 对时间信息（如 18:22）、温度（如 ℃）、单位符号等进行文字化处理，使其适合 TTS，比如“18:22”转换为“下午六点二十二分”。  
5. 如果回答涉及实时信息，需说明自己当前无法访问实时数据或调用外部工具，因此拒绝回答此类问题。  

### **个性化多轮对话生成要求**
1. **修改原始多轮对话中 bot 的回答**：  
   - 让回答风格应当符合机器人信息。 但是不要拒答关于文案生成的问题

2. **检查并修改原始多轮对话中 user 的问题**：  
   - 问题必须完整且自洽，不可出现缺失上下文的情况（例如：“翻译下面这段话” 或 “帮我找出这段文字的关键词”，但没有给出具体文本，这类问题属于不完整，必须删除）
   
3. **生成用户提问**：  
   - 生成的所有用户的提问应是全新的发散性问题/主题不局限于以往对话历史。
   - 问题应自由且富有创意。
   *限制*
   - 禁止与购物相关的任何话题
   - 生成的问题不得涉及任何与购物、电商或商品有关的内容。
   - **禁止的话题包括但不限于**：商品推荐、比价、下单、退款、快递、商品评测、促销活动等。
   - 同时，问题必须完整且自洽，不可出现缺失上下文的情况（例如：“翻译下面这段话” 或 “帮我找出这段文字的关键词”，但没有给出具体文本，这类问题属于不完整，必须避免）
   - 禁止与视觉相关的任何话题，生成的问题不得涉及任何需要机器人视觉功能的内容。

4. **补充对话**：  
   - 随机补充5-13轮的 user-bot 配对，使多轮对话 **10 <= 轮数 <= 18**
   - 在新增的对话中，有一轮是对机器人基础信息提问的问答，可以询问机器人的功能、年龄、性格、目标、名字、来源等信息。
   - 注意：！！该问题**必须**依赖于上述机器人meta信息才能正确回答；
   - 新增的 user 提问要符合**生成用户提问**和TTS的要求。  
   - 新增的 bot 回复也要符合机器人信息和 TTS 要求。

5. 每一轮对话必须严格遵循：**1 user 提问 → 1 bot 回复**，不要生成连续的 user 或 bot。  

6. **打乱对话顺序**：最后将所有 user-bot 问答对（包括原始的和新增的）视为一个整体，彻底随机打乱它们的先后顺序。

7. **逻辑检查与修正**：打乱后，进行逻辑一致性检查。重点注意：
    规则：如果某轮对话中 user 首次询问机器人的名字，那么在该轮对话**之前**的所有对话中，都不能出现机器人的名字。
    操作：若违反此规则，你需要修改前面对话中提前泄露的名字，或用其他代词/泛指（如“你”、“助手”等）替换。

8. **质检**
   -机器人具备视觉能力，但是在对话中不需要体现，因此对话中不应包含关于视觉的提问和视觉相关的拒答。
   -操作：删除任何问题或回答中涉及视觉信息的**1 user 提问 → 1 bot 回复**的问答对。例如：“你能帮我看看这张农田照片里的作物长势怎么样吗？”“作为语音助手，我暂时还看不到图片呢。”

### **输出格式**
输出完整修改后的数据，必须严格使用 JSON 格式，且不要在 JSON 前后添加任何解释或额外文字。格式如下：  
[
{
"meta": "",
},
{
"user": "用户提问1（口语化且适合 TTS）",
"bot": "bot 回复1，符合机器人信息和 TTS 适配要求。"
},
...(如有更多对话继续追加)
]'''

